import './neon-rating-field.scss';
import { AbstractInputField } from '../shared/abstract-input-field';
import { createElement, updateDynamicText, updateDynamicAttribute, dynamicAttr, replace, updateDynamicProperty, useElementIf, updateConditionalElements, dynamicProperty } from '../shared/dom-manipulation';
import { addTranslationListener } from '@ps-refarch-ux/mfe-utils';
import { getRequiredOnlyValidators } from '../shared/validation-engine/validate-engine';
const expandedSatisfactionRatingArray = {
    1: 'emotion-frowning-outline',
    2: 'emotion-unhappy-outline',
    3: 'emotion-neutral-outline',
    4: 'emotion-smiling-outline',
    5: 'emotion-grinning-outline'
};
const expandedSatisfactionRatingFilledArray = {
    1: 'emotion-frowning',
    2: 'emotion-unhappy',
    3: 'emotion-neutral',
    4: 'emotion-smiling',
    5: 'emotion-grinning'
};
const simpleSatisfactionRatingArray = {
    1: 'emotion-unhappy-outline',
    2: 'emotion-neutral-outline',
    3: 'emotion-smiling-outline'
};
const simpleSatisfactionRatingFilledArray = {
    1: 'emotion-unhappy',
    2: 'emotion-neutral',
    3: 'emotion-smiling'
};
const simpleSatisfactionRatingArray2 = {
    1: 'emotion-unhappy-outline',
    2: 'emotion-smiling-outline'
};
const simpleSatisfactionRatingFilledArray2 = {
    1: 'emotion-unhappy',
    2: 'emotion-smiling'
};
export class NeonRatingField extends AbstractInputField {
    constructor() {
        super();
        this.widgetTag = 'neon-rating-field';
        this.isIdRequired = true;
        this.isUsesLabel = false;
        this.inputElement = this.renderInputElement();
        this.readOnlyElement = createElement('div', { attrs: { class: 'neon-rating-field-wrapper-readonly neon-input-field-first' } });
    }
    get value() {
        return this._value;
    }
    set value(value) {
        //log(`set value(${value}) called`);
        this.setValue(value);
        this.setReadonlyText();
    }
    get modelValue() {
        return this._modelValue;
    }
    set modelValue(value) {
        //log(`set modelValue(${value})`);
        value = this.validateModelValueType(value);
        const modelValueChanged = this.setModelValue(value);
        if (modelValueChanged) {
            //only show the validation message IF an error message is already showing.
            const showValidationResult = !this.errorElement.classList.contains('neon-sr-only');
            this.validateWidget(showValidationResult);
        }
        this.setReadonlyText();
    }
    setValue(value, skip) {
        if (isNaN(value) || typeof value !== 'string') {
            this._value = '';
        }
        else {
            this._value = value;
        }
        if (skip !== true) {
            this.setModelValue(Number(this._value), true);
        }
    }
    validateModelValueType(modelValue) {
        if (typeof modelValue === 'number' || !isNaN(modelValue)) {
            if (modelValue >= 0 && modelValue <= 5) {
                return modelValue;
            }
        }
        return undefined;
    }
    setModelValue(modelValue, skip) {
        if (this.modelValue == null && modelValue == null) {
            return false;
        }
        this._modelValue = modelValue;
        const originalCheckedElement = this.inputElement.querySelector('input[type=radio]:checked');
        const modelValueString = String(Math.floor(this._modelValue || 0));
        for (const inputEle of Array.from(this.inputElement.querySelectorAll('input[type=radio]'))) {
            inputEle.checked = modelValueString === inputEle.value;
        }
        const newCheckedElement = this.inputElement.querySelector('input[type=radio]:checked');
        if (skip !== true) {
            this.setValue(String(this._modelValue || ''), true);
        }
        updateDynamicAttribute(this, 'data-icon');
        updateDynamicAttribute(this, 'aria-label');
        return originalCheckedElement !== newCheckedElement;
    }
    generateValidationRules() {
        this.validators = getRequiredOnlyValidators(this.getAttribute('data-is-required') === 'true');
        this.addCustomValidateToValidators();
    }
    //Any attribute that should be watched for changes should be listed here.
    static get observedAttributes() {
        return super.observedAttributes.concat([
            'data-type',
            'data-size'
        ]);
    }
    //when the attributes change this will run
    attributeChanged(attrName, oldVal, newVal) {
        super.attributeChanged(attrName, oldVal, newVal);
        switch (attrName) {
            case 'data-type':
                updateDynamicAttribute(this, 'data-type');
                updateDynamicAttribute(this, 'data-icon');
                updateDynamicAttribute(this, 'aria-label');
                updateConditionalElements(this);
                break;
            case 'disabled':
                updateDynamicProperty(this, 'disabled');
                break;
            case 'data-is-read-only':
                updateDynamicAttribute(this, 'readonly');
                updateDynamicAttribute(this, 'data-icon');
                break;
            case 'data-size':
                updateDynamicAttribute(this, 'data-icon');
                break;
            default:
                break;
        }
    }
    getRatingLength() {
        if (this.getAttribute('data-type') !== null) {
            switch (this.getAttribute('data-type')) {
                case 'simple-satisfaction-rating-2':
                    return 2;
                case 'simple-satisfaction-rating':
                    return 3;
                case '3-star-rating':
                    return 3;
                default: return 5;
            }
        }
        return 0;
    }
    getAriaLabel(count) {
        const iconName = this.getIcon(count);
        switch (iconName) {
            case 'emotion-frowning':
            case 'emotion-frowning-outlie':
                return 'emotion-frowning';
            case 'emotion-unhappy':
            case 'emotion-unhappy-outlie':
                return 'emotion-unhappy';
            case 'emotion-neutral':
            case 'emotion-neutral-outlie':
                return 'emotion-neutral';
            case 'emotion-smiling':
            case 'emotion-smiling-outlie':
                return 'emotion-smiling';
            case 'emotion-grinning':
            case 'emotion-grinning-outlie':
                return 'emotion-grinning';
        }
        return count + '';
    }
    renderReadOnlyRating() {
        const readonly = [];
        for (let i = 1; i <= 5; i++) {
            readonly.push(createElement('neon-2_20_1-icon', {
                attrs: {
                    'data-icon': dynamicAttr(() => { return this.getReadOnlyIcon(i); }),
                    'data-size': dynamicAttr(() => { return this.getIconSize(); }),
                    class: dynamicAttr(() => { return this.getReadOnlyIconClass(i) + ' ' + this.getReadonlyIocnRenderclass(i); })
                }
            }));
        }
        return readonly;
    }
    getIcon(count, filledStatus) {
        if (filledStatus === 'solid') {
            switch (this.getAttribute('data-type')) {
                case 'expanded-satisfaction-rating':
                    return expandedSatisfactionRatingFilledArray[count];
                    break;
                case 'simple-satisfaction-rating':
                    return simpleSatisfactionRatingFilledArray[count];
                    break;
                case 'simple-satisfaction-rating-2':
                    return simpleSatisfactionRatingFilledArray2[count];
                    break;
                default:
                    return 'star-solid';
                    break;
            }
        }
        else {
            switch (this.getAttribute('data-type')) {
                case 'expanded-satisfaction-rating':
                    return expandedSatisfactionRatingArray[count];
                    break;
                case 'simple-satisfaction-rating':
                    return simpleSatisfactionRatingArray[count];
                    break;
                case 'simple-satisfaction-rating-2':
                    return simpleSatisfactionRatingArray2[count];
                    break;
                default:
                    return 'star-outline';
                    break;
            }
        }
    }
    getReadOnlyIcon(count) {
        const length = this.getRatingLength();
        switch (this.getAttribute('data-type')) {
            case 'expanded-satisfaction-rating': return expandedSatisfactionRatingFilledArray[count];
            case 'simple-satisfaction-rating': return simpleSatisfactionRatingFilledArray[count];
            case 'simple-satisfaction-rating-2': return simpleSatisfactionRatingFilledArray2[count];
        }
        if (count > this.modelValue && count - 1 < this.modelValue && this.isReadOnly && count <= length) {
            return 'star-half';
        }
        return (count <= length) ? 'star-solid' : '';
    }
    getReadonlyIocnRenderclass(count) {
        if (count > this.getRatingLength()) {
            return ' neon-rating-field-readonly-rates ';
        }
        return '';
    }
    getReadOnlyIconClass(count) {
        switch (this.getHoverFillType()) {
            case 'multiple':
                //This should return .neon-rating-field-readonly-star-active or  .neon-rating-field-readonly-inactive
                if ((count > this.modelValue && count - 1 < this.modelValue) || count <= this.modelValue) {
                    return 'neon-rating-field-readonly-icon-active';
                }
                break;
            case 'single':
                //This should return .neon-rating-field-readonly-emoji-active or  .neon-rating-field-readonly-inactive
                if (this.modelValue === count || (count < this.modelValue && count + 1 > this.modelValue)) {
                    return 'neon-rating-field-readonly-icon-active';
                }
                break;
            default:
        }
        return 'neon-rating-field-readonly-icon-inactive';
    }
    getIconSize() {
        if (this.getAttribute('data-is-read-only') === 'true' && this.getAttribute('data-size')) {
            const iconSize = this.getAttribute('data-size');
            return iconSize !== null ? iconSize : 'x-large';
        }
        return 'x-large';
    }
    isRatingFieldOptionSolid(count) {
        if (this.getHoverFillType() === 'single') {
            return Math.floor(this.modelValue || 0) === count;
        }
        else {
            return Math.floor(this.modelValue || 0) >= count;
        }
    }
    getHoverFillType() {
        switch (this.getAttribute('data-type')) {
            case 'expanded-satisfaction-rating':
            case 'simple-satisfaction-rating':
            case 'simple-satisfaction-rating-2':
                return 'single';
            default:
                return 'multiple';
        }
    }
    renderRatingOption(count) {
        return createElement('label', {
            attrs: {
                class: dynamicAttr(() => {
                    return 'neon-rating-field-option' +
                        (this.isRatingFieldOptionSolid(count) ? ' neon-rating-field-option-solid' : '');
                }),
                'aria-label': dynamicAttr(() => {
                    return this.getAriaLabel(count);
                })
            }
        }, createElement('input', {
            attrs: {
                type: 'radio',
                id: dynamicAttr(() => {
                    return this.getAttribute('id') + '-rating-field-' + count;
                }),
                name: dynamicAttr(() => {
                    return this.getAttribute('id') + '-rating-field';
                }),
                value: String(count),
                class: 'neon-rating-input neon-sr-only',
                readonly: dynamicAttr(() => {
                    return this.getAttribute('data-is-read-only') === 'true' ? '' : undefined;
                })
            },
            properties: {
                disabled: dynamicProperty(() => { return this.getDisabledStatus(); })
            },
            listeners: {
                'input': (event) => {
                    //Always keep this._value up to date with what the user has selected.
                    //This allows the inputChange() function to perform as expected.
                    this._value = event.target.value;
                    this.inputChange();
                },
                'blur': (event) => { return this.focusLost(event); }
            }
        }), createElement('neon-2_20_1-icon', {
            attrs: {
                'data-icon': dynamicAttr(() => { return this.getIcon(count, 'outline'); }),
                'data-size': 'x-large',
                'data-size-mobile': 'xx-large',
                class: 'neon-rating-field-icon-outline'
            }
        }), createElement('neon-2_20_1-icon', {
            attrs: {
                'data-icon': dynamicAttr(() => { return this.getIcon(count, 'solid'); }),
                'data-size': 'x-large',
                'data-size-mobile': 'xx-large',
                class: 'neon-rating-field-icon-solid'
            }
        }));
    }
    renderInputElement() {
        return createElement('div', {
            attrs: {
                id: dynamicAttr(() => {
                    return this.getAttribute('id') + '-neon-rating-field';
                }),
                class: dynamicAttr(() => {
                    //This dynamic class will return neon-rating-field-hover-fill-single or neon-rating-field-hover-fill-multiple
                    return 'neon-rating-field-wrapper neon-input-field-first neon-rating-field-hover-fill-' + this.getHoverFillType();
                })
            }
        }, this.renderRatingOption(1), this.renderRatingOption(2), useElementIf(() => {
            return this.getRatingLength() >= 3;
        }, () => { return this.renderRatingOption(3); }), useElementIf(() => {
            return this.getRatingLength() >= 4;
        }, () => { return this.renderRatingOption(4); }), useElementIf(() => {
            return this.getRatingLength() >= 5;
        }, () => { return this.renderRatingOption(5); }));
    }
    redrawInput() {
        if (this.isReadOnly) {
            //When readonly becomes true, we need to put the readonly div into the DOM, but only if it isn't there already.
            this.readOnlyElement.replaceChildren(...this.renderReadOnlyRating());
            if (!this.readOnlyElement.isConnected) {
                replace(this.readOnlyElement, this.querySelector('.neon-rating-field-wrapper'));
            }
        }
        else {
            //When readonly becomes false, if the readonly div is already in the DOM, we need to replace it with the input field.
            if (!this.inputElement.isConnected && this.readOnlyElement.childNodes.length > 0) {
                replace(this.inputElement, this.readOnlyElement);
            }
            else {
                replace(this.inputElement, this.querySelector('.neon-rating-field-wrapper-readonly'));
            }
        }
    }
    connectedCallback() {
        super.connectedCallback();
        this.i18nUnsubscribe = addTranslationListener(() => {
            updateDynamicText(this);
        });
    }
    disconnectedCallback() {
        if (this.i18nUnsubscribe != null) {
            this.i18nUnsubscribe();
            this.i18nUnsubscribe = undefined;
        }
    }
}
